import{_ as a,o as r,c as n,af as s}from"./chunks/framework.D75dE8dq.js";const g=JSON.parse('{"title":"第一章 课程总览","description":"","frontmatter":{},"headers":[],"relativePath":"pages/markdown/01.md","filePath":"pages/markdown/01.md","lastUpdated":1782342217000}'),i={name:"pages/markdown/01.md"};function e(o,t,d,p,l,h){return r(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="第一章-课程总览" tabindex="-1">第一章 课程总览 <a class="header-anchor" href="#第一章-课程总览" aria-label="Permalink to &quot;第一章 课程总览&quot;">​</a></h1><h2 id="_1-什么是markdown" tabindex="-1">1. 什么是Markdown？ <a class="header-anchor" href="#_1-什么是markdown" aria-label="Permalink to &quot;1. 什么是Markdown？&quot;">​</a></h2><p><strong>简介</strong></p><hr><p>• 定义：Markdown 是一种「纯文本→HTML」的轻量级标记语言。</p><p>• 特点：语法像打字聊天，10 秒成排版。</p><p>• 文件扩展名：.md 或 .markdown（GitHub、Gitee、Typora 通用）。</p><p><strong>Markdown 5 大刚需场景</strong></p><hr><p>① 微信公众号 / 知乎一键排版</p><p>② GitHub README &amp; 开源文档</p><p>③ Notion、Obsidian 等知识库导入</p><p>④ AI 提示词模板（ChatGPT、豆包、Kimi、文心一言等）</p><p>⑤ 电子书、博客静态网站（VitePress、Hexo）</p><p><strong>对比记忆表</strong></p><hr><table tabindex="0"><thead><tr><th>工具</th><th>学习成本</th><th>输出格式</th><th>适合人群</th></tr></thead><tbody><tr><td>Word</td><td>高</td><td>.docx</td><td>行政办公</td></tr><tr><td>Markdown</td><td>极低</td><td>HTML/PDF/ePub</td><td>开发者/自媒体</td></tr><tr><td>LaTeX</td><td>高</td><td>PDF</td><td>学术排版</td></tr></tbody></table><hr><h2 id="_2-为什么要学markdown" tabindex="-1">2. 为什么要学Markdown？ <a class="header-anchor" href="#_2-为什么要学markdown" aria-label="Permalink to &quot;2. 为什么要学Markdown？&quot;">​</a></h2><p><strong>痛点直击</strong></p><hr><p>• 写 Word：调字号、刷格式，排版 30 min，写作 5 min</p><p>• 写 Markdown：打字同时完成排版，写作 5 min，排版 0 min</p><p>→ 省下的时间 = 多写 5 篇技术博客</p><p><strong>市场数据</strong></p><hr><table tabindex="0"><thead><tr><th>平台</th><th>Markdown 内容占比</th><th>年增速</th></tr></thead><tbody><tr><td>GitHub</td><td>93% README</td><td>+12%</td></tr><tr><td>知乎专栏</td><td>67% 技术文章</td><td>+35%</td></tr><tr><td>微信公众号</td><td>28% 技术号</td><td>+58%</td></tr></tbody></table><p><strong>结论</strong>：不会 Markdown = 错过 1/3 流量红利</p><p><strong>一句话总结</strong></p><hr><p>“写作 5 分钟，排版 0 分钟，SEO 全自动”——这就是当下创作者标配技能。</p><h2 id="_3-5分钟完成你第一个markdown文件" tabindex="-1">3. 5分钟完成你第一个Markdown文件 <a class="header-anchor" href="#_3-5分钟完成你第一个markdown文件" aria-label="Permalink to &quot;3. 5分钟完成你第一个Markdown文件&quot;">​</a></h2><p><strong>准备工具（1 分钟）</strong></p><hr><ol><li>在线编辑器：用电脑打开 <a href="https://www.w3cschool.cn/tools/index?name=markdown" target="_blank" rel="noreferrer">w3cschool 在线 Markdown</a>（免安装）</li><li>本地推荐：Typora 1.8 绿色版（国内镜像下载）</li><li>新建文件：右键 → 新建 → 命名 <code>hello.md</code></li></ol><p><strong>3 行代码速成模板（复制即用）</strong></p><hr><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 我的第一篇 Markdown</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">大家好，这是 </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**第一段**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 文字。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 快速</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 简洁</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 高效</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>把上面内容粘进 <code>hello.md</code>，立刻看到左侧源码、右侧预览。</p><p><strong>一键导出 &amp; 分享（1 分钟）</strong></p><hr><p>• <strong>Typora</strong>：Ctrl+Shift+E → 导出 PDF/HTML</p><p>• <strong>在线编辑器</strong>：点击「下载为md」→ 保存 Markdown 文件到本地</p><p>• <strong>GitHub</strong>：拖入仓库，自动渲染 README</p><h2 id="_4-学前准备-10-秒装好-4-大工具-在线-本地-插件-手机" tabindex="-1">4. 学前准备：10 秒装好 4 大工具（在线 + 本地 + 插件 + 手机） <a class="header-anchor" href="#_4-学前准备-10-秒装好-4-大工具-在线-本地-插件-手机" aria-label="Permalink to &quot;4. 学前准备：10 秒装好 4 大工具（在线 + 本地 + 插件 + 手机）&quot;">​</a></h2><p><strong>在线即用</strong></p><hr><p>w3cschool <a href="https://www.w3cschool.cn/tools/index?name=markdown" target="_blank" rel="noreferrer">在线 Markdown 编辑器</a> • 打开即用，无需下载 • 手机浏览器也能写</p><p><strong>本地极速安装</strong></p><hr><p>工具</p><ul><li>Typora</li><li>VS Code</li><li><a href="https://www.trae.cn/login?utm_source=training&amp;utm_medium=CPA_w3cschool&amp;utm_campaign=live" target="_blank" rel="noreferrer">Trae</a></li></ul><p><strong>必装 3 个插件（VS Code 内 Ctrl+Shift+X 搜索）</strong></p><hr><ol><li>Markdown All in One（快捷键、目录）</li><li>Paste Image（Ctrl+Alt+V 直接贴图）</li><li>Chinese (Simplified) Language Pack（中文界面）</li></ol><p><strong>手机端方案）</strong></p><hr><p>• iOS/Android：Obsidian • 同步：把 <code>.md</code> 文件丢进「iCloud/坚果云」即可多端秒同步</p>`,58)])])}const c=a(i,[["render",e]]);export{g as __pageData,c as default};
